const now = new Date();
const dateStr = now.toISOString().split('T')[0].replace(/-/g, '');
const dayOfWeek = now.getDay();
const dayOfMonth = now.getDate();

// Determine backup type
let backupType = 'incremental';
if (dayOfMonth === 1) {
  backupType = 'full';
} else if (dayOfWeek === 0) { // Sunday
  backupType = 'full';
}

const backupDir = '/backups';
const filename = `greevo_${backupType}_${dateStr}.sql.gz`;
const filepath = `${backupDir}/${filename}`;

// Tables to backup
const allTables = [
  'clients', 'client_credentials', 'contacts', 'lead_activities',
  'email_campaigns', 'deals', 'tracked_keywords', 'keyword_rankings',
  'backlinks', 'site_health_checks', 'competitor_tracking',
  'analytics_snapshots', 'report_schedules', 'audit_logs',
  'workflow_execution_stats', 'rate_limits'
];

// Incremental: only tables with recent changes
const incrementalTables = [
  'contacts', 'lead_activities', 'deals', 'keyword_rankings',
  'backlinks', 'site_health_checks', 'competitor_tracking',
  'analytics_snapshots', 'audit_logs', 'workflow_execution_stats'
];

const tables = backupType === 'full' ? allTables : incrementalTables;

return [{
  json: {
    backup_type: backupType,
    filename: filename,
    filepath: filepath,
    backup_dir: backupDir,
    date_str: dateStr,
    tables: tables,
    retention_days: backupType === 'full' ? 30 : 7,
    started_at: now.toISOString()
  }
}];

const output = $input.first().json;
const planData = $node['Plan Backup'].json;
const backupOutput = output.stdout || '';
const success = backupOutput.includes('EXISTS');

// Parse file size if available
let fileSizeBytes = 0;
if (success) {
  const match = backupOutput.match(/(\d+)\s/);
  if (match) fileSizeBytes = parseInt(match[1]);
}

const expiresAt = new Date();
expiresAt.setDate(expiresAt.getDate() + planData.retention_days);

return [{
  json: {
    ...planData,
    success: success,
    file_size_bytes: fileSizeBytes,
    file_size_mb: Math.round(fileSizeBytes / 1024 / 1024 * 100) / 100,
    expires_at: expiresAt.toISOString(),
    completed_at: new Date().toISOString()
  }
}];
